// SetLockedByUser of the project to the related item.
// Sets o.R.LockedByUser to related.
// Adds o to related.R.LockedByUserProjects.
func (o *Project) SetLockedByUser(ctx context.Context, exec boil.ContextExecutor, insert bool, related *AppUser) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"project\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"locked_by_user_id"}),
		strmangle.WhereClause("\"", "\"", 2, projectPrimaryKeyColumns),
	)
	values := []interface{}{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.LockedByUserID, related.ID)
	if o.R == nil {
		o.R = &projectR{
			LockedByUser: related,
		}
	} else {
		o.R.LockedByUser = related
	}

	if related.R == nil {
		related.R = &appUserR{
			LockedByUserProjects: ProjectSlice{o},
		}
	} else {
		related.R.LockedByUserProjects = append(related.R.LockedByUserProjects, o)
	}

	return nil
}

// RemoveLockedByUser relationship.
// Sets o.R.LockedByUser to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Project) RemoveLockedByUser(ctx context.Context, exec boil.ContextExecutor, related *AppUser) error {
	var err error

	queries.SetScanner(&o.LockedByUserID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("locked_by_user_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.LockedByUser = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.LockedByUserProjects {
		if queries.Equal(o.LockedByUserID, ri.LockedByUserID) {
			continue
		}

		ln := len(related.R.LockedByUserProjects)
		if ln > 1 && i < ln-1 {
			related.R.LockedByUserProjects[i] = related.R.LockedByUserProjects[ln-1]
		}
		related.R.LockedByUserProjects = related.R.LockedByUserProjects[:ln-1]
		break
	}
	return nil
}

